1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"os"
9		"os/exec"
10		"path/filepath"
11		"reflect"
12		"strings"
13		"testing"
14	)
15	
16	// These tests exercise resolve the way a user does: a config file argument,
17	// one JSON request on stdin, and the observable exit status / stdout / stderr
18	// of the whole command. They never open a network connection and do not need
19	// the upstreams to exist, so they reproduce deterministically offline.
20	
21	// helperEnv guards TestHelperProcess: only a child spawned with this variable
22	// set hands its arguments over to the real main; in an ordinary `go test`
23	// run the test is a no-op.
24	const helperEnv = "CONTRACTSENTINEL_HELPER_PROCESS"
25	
26	// TestHelperProcess is the re-executed test binary: arguments after "--"
27	// become the command's own os.Args, then main runs as normal (including its
28	// non-zero os.Exit on failure, which the parent observes via exit status).
29	func TestHelperProcess(t *testing.T) {
30		if os.Getenv(helperEnv) != "1" {
31			return
32		}
33		for i, a := range os.Args {
34			if a == "--" {
35				os.Args = append([]string{os.Args[0]}, os.Args[i+1:]...)
36				break
37			}
38		}
39		main()
40		os.Exit(0)
41	}
42	
43	// resolveResult is everything the parent can observe from one resolve run.
44	type resolveResult struct {
45		stdout   []byte
46		stderr   []byte
47		exitCode int
48	}
49	
50	// runResolveCLI writes config to a temp file, spawns the helper test binary
51	// with "resolve <config>" and feeds the request on stdin.
52	func runResolveCLI(t *testing.T, config, request string) resolveResult {
53		t.Helper()
54	
55		dir := t.TempDir()
56		configPath := filepath.Join(dir, "config.json")
57		if err := os.WriteFile(configPath, []byte(config), 0o600); err != nil {
58			t.Fatalf("write config: %v", err)
59		}
60	
61		cmd := exec.Command(os.Args[0], "-test.run=^TestHelperProcess$", "--", "resolve", configPath)
62		cmd.Env = append(os.Environ(), helperEnv+"=1")
63		cmd.Stdin = strings.NewReader(request)
64		var stdout, stderr bytes.Buffer
65		cmd.Stdout = &stdout
66		cmd.Stderr = &stderr
67	
68		err := cmd.Run()
69		exitCode := 0
70		if err != nil {
71			var exitErr *exec.ExitError
72			if errors.As(err, &exitErr) {
73				exitCode = exitErr.ExitCode()
74			} else {
75				t.Fatalf("run resolve helper: %v", err)
76			}
77		}
78		return resolveResult{stdout: stdout.Bytes(), stderr: stderr.Bytes(), exitCode: exitCode}
79	}
80	
81	// decodeOneJSON decodes exactly one JSON value and requires nothing but
82	// trailing whitespace afterwards, so "one JSON object in the stream" is
83	// asserted instead of merely "a prefix parses".
84	func decodeOneJSON(t *testing.T, data []byte, what string, v any) {
85		t.Helper()
86		dec := json.NewDecoder(bytes.NewReader(data))
87		if err := dec.Decode(v); err != nil {
88			t.Fatalf("%s is not a single JSON object: %v\n%s", what, err, data)
89		}
90		if err := dec.Decode(&struct{}{}); err != io.EOF {
91			t.Fatalf("%s contains more than one JSON value: %v\n%s", what, err, data)
92		}
93	}
94	
95	const cliSuccessConfig = `{
96	  "routes": [
97	    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"}
98	  ]
99	}`
100	
101	const cliSuccessRequest = `{"method":"GET","target":"/api/items?a=1&a=&x=%2f+&flag"}`
102	
103	func TestResolveCLISuccess(t *testing.T) {
104		res := runResolveCLI(t, cliSuccessConfig, cliSuccessRequest)
105	
106		if res.exitCode != 0 {
107			t.Fatalf("exit code = %d, want 0; stderr: %s", res.exitCode, res.stderr)
108		}
109		if len(res.stderr) != 0 {
110			t.Fatalf("stderr = %q, want empty", res.stderr)
111		}
112	
113		var success struct {
114			RouteID     string `json:"routeId"`
115			UpstreamURL string `json:"upstreamURL"`
116		}
117		decodeOneJSON(t, res.stdout, "stdout", &success)
118	
119		if success.RouteID != "api" {
120			t.Errorf("routeId = %q, want api", success.RouteID)
121		}
122		wantURL := "http://api.internal/v1/items?a=1&a=&x=%2f+&flag"
123		if success.UpstreamURL != wantURL {
124			t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, wantURL)
125		}
126	
127		// The raw query must survive byte for byte: '&' is emitted literally
128		// (HTML escaping off), and the stream is just the one compact result
129		// object with no demo, usage or debug text mixed in.
130		if !bytes.Contains(res.stdout, []byte("&")) {
131			t.Errorf("stdout should contain raw '&': %s", res.stdout)
132		}
133		if bytes.Contains(res.stdout, []byte("\\u0026")) {
134			t.Errorf("stdout must not unicode-escape '&': %s", res.stdout)
135		}
136		var keys map[string]json.RawMessage
137		decodeOneJSON(t, res.stdout, "stdout", &keys)
138		if len(keys) != 2 || keys["routeId"] == nil || keys["upstreamURL"] == nil {
139			t.Errorf("stdout should be exactly {routeId, upstreamURL}, got keys: %v", keys)
140		}
141	}
142	
143	func TestResolveCLIInvalidConfigRejectedEvenWhenFirstRouteHits(t *testing.T) {
144		// A GET /api request would hit route 1; route 2 ("admin") can never
145		// match, but its second queryTransforms rule uses the unsupported
146		// "delete" op, which must reject the whole configuration up front.
147		config := `{
148		  "routes": [
149		    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
150		    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin", "upstream": "http://admin.internal",
151		     "queryTransforms": [
152		       {"op": "set", "name": "a", "value": "1"},
153		       {"op": "delete", "name": "x"}
154		     ]}
155		  ]
156		}`
157		res := runResolveCLI(t, config, cliSuccessRequest)
158	
159		if res.exitCode == 0 {
160			t.Fatalf("exit code = 0, want non-zero")
161		}
162		if len(res.stdout) != 0 {
163			t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
164		}
165	
166		var fail struct {
167			Code   string `json:"code"`
168			Reason string `json:"reason"`
169		}
170		decodeOneJSON(t, res.stderr, "stderr", &fail)
171		if fail.Code != "invalid_config" {
172			t.Errorf("code = %q, want invalid_config", fail.Code)
173		}
174		if fail.Reason == "" {
175			t.Fatal("reason must be non-empty")
176		}
177		for _, want := range []string{"route 2", `"admin"`, "rule 2"} {
178			if !strings.Contains(fail.Reason, want) {
179				t.Errorf("reason = %q, want substring %q (route position, id and rule index)", fail.Reason, want)
180			}
181		}
182	}
183	
184	// TestResolveCLIRouteFieldTypeLocated rejects valid JSON whose second route
185	// has a wrong-typed methods field, even when the request would hit the first
186	// route; the stderr reason must name route 2 and its orders id and say
187	// methods must be an array, instead of blaming the whole document's JSON.
188	func TestResolveCLIRouteFieldTypeLocated(t *testing.T) {
189		badConfig := `{
190		  "routes": [
191		    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
192		    {"id": "orders", "methods": "GET", "pathPrefix": "/api/orders", "upstream": "http://orders.internal"}
193		  ]
194		}`
195		res := runResolveCLI(t, badConfig, cliSuccessRequest)
196	
197		if res.exitCode == 0 {
198			t.Fatalf("exit code = 0, want non-zero")
199		}
200		if len(res.stdout) != 0 {
201			t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
202		}
203	
204		var fail struct {
205			Code   string `json:"code"`
206			Reason string `json:"reason"`
207		}
208		decodeOneJSON(t, res.stderr, "stderr", &fail)
209		if fail.Code != "invalid_config" {
210			t.Errorf("code = %q, want invalid_config", fail.Code)
211		}
212		if strings.Contains(fail.Reason, "not valid JSON") {
213			t.Fatalf("field type error must not read as a JSON syntax failure: %q", fail.Reason)
214		}
215		for _, want := range []string{"route 2", `"orders"`, "methods must be an array"} {
216			if !strings.Contains(fail.Reason, want) {
217				t.Errorf("reason = %q, want substring %q", fail.Reason, want)
218			}
219		}
220	
221		// After the second route is repaired to an array, the same request
222		// resolves normally and the first route still matches.
223		fixedConfig := strings.Replace(badConfig, `"methods": "GET", "pathPrefix": "/api/orders"`,
224			`"methods": ["GET"], "pathPrefix": "/api/orders"`, 1)
225		ok := runResolveCLI(t, fixedConfig, cliSuccessRequest)
226		if ok.exitCode != 0 {
227			t.Fatalf("exit code = %d, want 0; stderr: %s", ok.exitCode, ok.stderr)
228		}
229		var success struct {
230			RouteID     string `json:"routeId"`
231			UpstreamURL string `json:"upstreamURL"`
232		}
233		decodeOneJSON(t, ok.stdout, "stdout", &success)
234		if success.RouteID != "api" || success.UpstreamURL != "http://api.internal/v1/items?a=1&a=&x=%2f+&flag" {
235			t.Fatalf("got %+v", success)
236		}
237	
238		// A numeric entry inside an otherwise legal methods array is attributed
239		// to that route's methods, and must name the entry that failed.
240		numConfig := strings.Replace(badConfig, `"methods": "GET", "pathPrefix": "/api/orders"`,
241			`"methods": ["GET", 1], "pathPrefix": "/api/orders"`, 1)
242		num := runResolveCLI(t, numConfig, cliSuccessRequest)
243		if num.exitCode == 0 {
244			t.Fatalf("exit code = 0, want non-zero")
245		}
246		var numFail struct {
247			Code   string `json:"code"`
248			Reason string `json:"reason"`
249		}
250		decodeOneJSON(t, num.stderr, "stderr", &numFail)
251		if numFail.Code != "invalid_config" {
252			t.Fatalf("code = %q, want invalid_config", numFail.Code)
253		}
254		for _, want := range []string{"route 2", `"orders"`, "methods entry 2 must be a string"} {
255			if !strings.Contains(numFail.Reason, want) {
256				t.Errorf("reason = %q, want substring %q", numFail.Reason, want)
257			}
258		}
259	}
260	
261	// renameTwoRoutesConfig gives two routes that both match /api requests: a
262	// wide wildcard and a longer concrete route. Each carries a different rename,
263	// so a resolved request shows which route's transforms actually ran.
