275	// assertResolveSuccess runs one resolve and checks the full success contract
276	// at the command boundary: exit 0, empty stderr, exactly one
277	// {routeId, upstreamURL} JSON object on stdout with '&' never HTML-escaped.
278	func assertResolveSuccess(t *testing.T, res resolveResult) struct {
279		RouteID     string `json:"routeId"`
280		UpstreamURL string `json:"upstreamURL"`
281	} {
282		t.Helper()
283		if res.exitCode != 0 {
284			t.Fatalf("exit code = %d, want 0; stderr: %s", res.exitCode, res.stderr)
285		}
286		if len(res.stderr) != 0 {
287			t.Fatalf("stderr = %q, want empty", res.stderr)
288		}
289		var success struct {
290			RouteID     string `json:"routeId"`
291			UpstreamURL string `json:"upstreamURL"`
292		}
293		decodeOneJSON(t, res.stdout, "stdout", &success)
294		var keys map[string]json.RawMessage
295		decodeOneJSON(t, res.stdout, "stdout", &keys)
296		if len(keys) != 2 || keys["routeId"] == nil || keys["upstreamURL"] == nil {
297			t.Fatalf("stdout should be exactly {routeId, upstreamURL}, got keys: %v", keys)
298		}
299		if bytes.Contains(res.stdout, []byte("\\u0026")) {
300			t.Fatalf("stdout must not unicode-escape '&': %s", res.stdout)
301		}
302		return success
303	}
